import { getCurrentLanguage, translatePath } from "./i18n.js?v=2.49";
import { loadGameData } from "./game-data.js?v=1";

// Generated by scripts/sync-data.mjs. Light cone passives, relic set bonuses and
// artwork links all live in the JSON, including entries that used to be
// patched in by hand here.
export const LIGHTCONE_METADATA = await loadGameData('lightcones.json');
export const RELIC_SET_METADATA = await loadGameData('relic-sets.json');

export function getLightconeInfo(lcId, langOverride = null) {
  const lang = langOverride || getCurrentLanguage();
  const meta = LIGHTCONE_METADATA[lcId];
  if (!meta) {
    return {
      name: `Lightcone ${lcId}`,
      rarity: 4,
      path: translatePath("Unknown"),
      rawPath: "Unknown"
    };
  }
  const localizedName = meta.names?.[lang] || meta.names?.en || meta.names?.th || `Lightcone ${lcId}`;
  return {
    name: localizedName,
    rarity: meta.rarity,
    path: translatePath(meta.path),
    rawPath: meta.path
  };
}

export function getRelicSetInfo(setIdOrRelicId, langOverride = null) {
  const lang = langOverride || getCurrentLanguage();
  let setId = parseInt(setIdOrRelicId, 10);
  if (setId > 1000) {
    // If a 5-digit relic id like 61031 or 63045, extract the set id
    setId = Math.floor((setId % 10000) / 10);
  }
  const meta = RELIC_SET_METADATA[setId];
  if (!meta) {
    return {
      id: setId,
      name: `Relic Set ${setId}`
    };
  }
  const localizedName = meta.names?.[lang] || meta.names?.en || meta.names?.th || `Relic Set ${setId}`;
  return {
    id: setId,
    name: localizedName,
    desc2: meta.descI18n?.[2]?.[lang] || meta.desc2,
    desc4: meta.descI18n?.[4]?.[lang] || meta.desc4
  };
}
